<script setup>
/*
 * 曲绘变更：选一个版本，列出这一版换过曲绘的曲目。
 * 竖排一列：旧图 → 旧画师 → ↓ → 新画师 → 新图，和定数变更卡一样只摆数据、不加说明。
 * 数据来自 files/lvmdf/history.json（每首歌的 [版本, 变体] 时间线）与 files/infos/illvariants.json（各变体的画师）。
 */
import { computed, onMounted, ref } from 'vue'
import { useOpenSong } from '../../api/openSong.js'
import { compareVersion, loadLevelHistory } from '../../api/levelHistory.js'
import { illLowPath } from '../../api/common.js'
import { loadIllVariants, variantArtist } from '../../api/illVariants.js'
import { useRemScale } from '../../utils/rem.js'
import ScrollTabs from '../../components/ui/ScrollTabs.vue'

useRemScale()

const openSong = useOpenSong()

const history = ref(null)
const illVariants = ref(null)
const selectedVersion = ref('')

// 版本栏最右侧钉一个「总览」：把所有换图记录按版本摊开，不用一版一版点
const OVERVIEW = '__overview__'
const pinnedTab = { value: OVERVIEW, label: '总览' }

const isOverview = computed(() => selectedVersion.value === OVERVIEW)

// 时间线上的值可能是单个变体，也可能是两张差分图的数组
const toList = (value) => (Array.isArray(value) ? value : [value])

const sameArt = (a, b) => JSON.stringify(toList(a)) === JSON.stringify(toList(b))

// 换下来的旧曲绘是负数变体（-1 / -2），差分图是正数变体（1 / 2）。
// 愚人节那几张差分图在游戏里是原版与差分版互切，不算换图——本页只统计真的被换掉的旧图
const isSwap = (from, to) => [...from, ...to].some((variant) => variant < 0)

// 版本栏只放换过曲绘的版本：没换图的版本不算曲绘历史，别混进来
const changedVersions = computed(() => {
  const data = history.value
  if (!data) return []
  const changed = new Set()
  for (const song of Object.values(data.songs)) {
    const timeline = song.ill || []
    // 第一个节点是「从这一版起用这张图」（收录或换图前的状态），之后值变了才是真的换图
    for (let index = 1; index < timeline.length; index += 1) {
      const from = toList(timeline[index - 1][1])
      const to = toList(timeline[index][1])
      if (sameArt(from, to)) continue
      // 差分图原版/差分版互切的节点跳过（详细页与历史页仍照常显示这些差分图）
      if (!isSwap(from, to)) continue
      changed.add(timeline[index][0])
    }
  }
  return [...changed].sort(compareVersion)
})

// 这一版的时间线上有节点的曲目，就是这一版换过曲绘的曲目；节点前一个值才是「换下来的那张」
const changes = computed(() => {
  const data = history.value
  const version = selectedVersion.value
  if (!data || !version) return []
  const list = []
  for (const [key, song] of Object.entries(data.songs)) {
    const timeline = song.ill || []
    const index = timeline.findIndex(([ver]) => compareVersion(ver, version) === 0)
    // 第一个节点只是「从这一版起用这张图」（曲目收录或换图前的状态），不是这一版换了图
    if (index <= 0) continue
    const from = toList(timeline[index - 1][1])
    const to = toList(timeline[index][1])
    // 值没变说明这一版只是把时间线切开，曲绘其实没换
    if (JSON.stringify(from) === JSON.stringify(to)) continue
    // 只是差分图与原版之间互切，不算换图
    if (!isSwap(from, to)) continue
    list.push({
      key,
      name: song.name,
      from: from.map((variant) => artOf(key, variant)),
      to: to.map((variant) => artOf(key, variant))
    })
  }
  return list.sort((a, b) => a.name.localeCompare(b.name, 'zh-Hans-CN'))
})

// 一张图 + 它的画师名义；差分图有两张时按变体号顺序往下排
const artOf = (key, variant) => ({
  variant,
  src: illLowPath(key, variant),
  artist: variantArtist(illVariants.value, key, variant) || ''
})

// 总览是历史变更汇总：一首曲目一张卡，把历次用过的曲绘按时间串起来，换过几次就有几个 ↓
const overviewSongs = computed(() => {
  const data = history.value
  if (!data) return []
  const list = []
  for (const [key, song] of Object.entries(data.songs)) {
    const timeline = song.ill || []
    const arts = []
    let last = null
    // 旧图（负数变体）之后的第一张新图是这条链的终点；差分图（正数变体）不进这条链
    let replaced = false
    for (const [, value] of timeline) {
      const variants = toList(value)
      const signature = JSON.stringify(variants)
      // 同一张图连着出现（时间线只是被版本切开）不算换图
      if (signature === last) continue
      last = signature
      const olds = variants.filter((variant) => variant < 0)
      if (olds.length) {
        for (const variant of olds) arts.push(artOf(key, variant))
        replaced = true
      } else if (replaced) {
        for (const variant of variants) arts.push(artOf(key, variant))
        replaced = false
      }
    }
    if (arts.length < 2) continue
    list.push({ key, name: song.name, arts })
  }
  return list.sort((a, b) => a.name.localeCompare(b.name, 'zh-Hans-CN'))
})

onMounted(async () => {
  const [data, variants] = await Promise.all([loadLevelHistory(), loadIllVariants()])
  history.value = data
  illVariants.value = variants
  // 默认停在最近一次换曲绘的版本，往前翻就是更早的换图记录
  selectedVersion.value = changedVersions.value[changedVersions.value.length - 1] || ''
})
</script>

<template>
  <div class="dt-page">
    <ScrollTabs
      v-model="selectedVersion"
      :items="changedVersions"
      :pinned="pinnedTab"
      class="ill-tabs"
      sticky
      aria-label="选择版本"
    />

    <!-- 总览：历史变更汇总，一首曲目一张卡，历次曲绘按时间竖着串起来 -->
    <div v-if="isOverview" class="change-grid change-grid--overview">
      <article
        v-for="item in overviewSongs"
        :key="item.key"
        class="change-card"
        :title="item.name"
        @click="openSong(item.key)"
      >
        <h2 class="card-name">{{ item.name }}</h2>

        <template v-for="(art, index) in item.arts" :key="`${art.variant}-${index}`">
          <div v-if="index" class="art-arrow" aria-hidden="true">↓</div>
          <div class="art-cell">
            <img :src="art.src" :alt="item.name" class="art-img" loading="lazy" />
            <p v-if="art.artist" class="art-artist">{{ art.artist }}</p>
          </div>
        </template>
      </article>
    </div>
    <div v-else class="change-grid">
      <article
        v-for="item in changes"
        :key="item.key"
        class="change-card"
        :title="item.name"
        @click="openSong(item.key)"
      >
        <h2 class="card-name">{{ item.name }}</h2>

        <div v-for="art in item.from" :key="`from-${art.variant}`" class="art-cell">
          <img :src="art.src" :alt="item.name" class="art-img" loading="lazy" />
          <p v-if="art.artist" class="art-artist">{{ art.artist }}</p>
        </div>

        <div class="art-arrow" aria-hidden="true">↓</div>

        <div v-for="art in item.to" :key="`to-${art.variant}`" class="art-cell">
          <img :src="art.src" :alt="item.name" class="art-img" loading="lazy" />
          <p v-if="art.artist" class="art-artist">{{ art.artist }}</p>
        </div>
      </article>
    </div>

    <div v-if="!isOverview && !changes.length && selectedVersion" class="dt-empty">
      这一版没有换过曲绘
    </div>
  </div>
</template>

