/**
 * 曲绘变体的画师与生效版本：/files/infos/illvariants.json 由 python/getLevelHistory.py 生成。
 * 变体号 0 是现用曲绘，负数是换下来的旧图（-1 第 1 版、-2 第 2 版），正数是差分类曲绘（愚人节等）。
 */
import { loadJson } from './jsonCache.js'

export const ILL_VARIANTS_PATH = '/files/infos/illvariants.json'

export function loadIllVariants() {
  return loadJson(ILL_VARIANTS_PATH)
}

/** 变体号在界面上的叫法：0 现用曲绘、-1 第 1 版、1 差分 1 */
export function variantLabel(variant) {
  const number = Number(variant)
  if (number === 0) return '现用曲绘'
  if (number < 0) return `第 ${-number} 版`
  return `差分 ${number}`
}

/** 某首歌某个变体的画师：表里同时记了名义与画师名，优先显示名义 */
export function variantArtist(illVariants, songId, variant) {
  const entry = illVariants?.songs?.[songId]?.variants?.[String(variant)]
  if (!entry) return ''
  return entry.nominal || entry.artist || ''
}

/** 一组变体的画师串联：同一首歌两张差分图时两边都列出来 */
export function variantArtists(illVariants, songId, variants) {
  const names = variants.map((variant) => variantArtist(illVariants, songId, variant)).filter(Boolean)
  // 去重但保留顺序：好几张图常常是同一个画师
  return [...new Set(names)].join(' / ')
}
